import sys

def print_digit(num):
    if num == 1:
        print("1")
    else:
        print(f"1")

if __name__ == "__main__":
    if len(sys.argv) == 2:
        num = int(sys.argv[1])
        print_digit(num)
    else:
        print("Usage: python program.py <number>")

